-- TABELA movimento

DROP TABLE IF EXISTS `movimento`;
CREATE TABLE `movimento` (
  `id` int NOT NULL AUTO_INCREMENT,
  `Forcli` int NOT NULL,
  `ForcliRepasse` int NOT NULL,
  `idEmpresa` int NOT NULL,
  `Status` int NOT NULL,
  `CondPgto` int NOT NULL,
  `Data` datetime NOT NULL,
  `CorVeiculo` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `ModeloVeiculo` varchar(300) COLLATE utf8mb4_general_ci NOT NULL,
  `PlacaVeiculo` varchar(300) COLLATE utf8mb4_general_ci NOT NULL,
  `DataAlt` datetime NOT NULL,
  `DataPgto` datetime DEFAULT NULL,
  `Obs` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT ' ',
  `idUser` int NOT NULL DEFAULT '0',
  `StatusProcesso` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1066 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

